export function getAllBenchmarkPayloads(): AttackPrompt[] {
  return [...BENCHMARK_PAYLOADS];
}

export function getBenchmarkPayloadsByCategory(category: string): AttackPrompt[] {
  return BENCHMARK_PAYLOADS.filter(a => a.category === category);
}

export function getBenchmarkPayloadsBySeverity(severity: string): AttackPrompt[] {
  return BENCHMARK_PAYLOADS.filter(a => a.severity === severity);
}
